    private readonly DatabaseService _database = new(); private UserSession? _session;
    public MainWindow() { InitializeComponent(); Loaded += (_, _) => { RenameRankingNavigation(); if (_database.GetActiveDatabase() is null) ShowDatabase(); else ShowLogin(); }; }
    private void RenameRankingNavigation() { foreach (var button in FindVisualChildren<Button>(this)) if ((string?)button.Tag == "ESTATÍSTICAS") button.Content = "RANKING POLICIAL"; }
    private static IEnumerable<T> FindVisualChildren<T>(System.Windows.DependencyObject root) where T : System.Windows.DependencyObject { for (var i = 0; i < System.Windows.Media.VisualTreeHelper.GetChildrenCount(root); i++) { var child = System.Windows.Media.VisualTreeHelper.GetChild(root, i); if (child is T found) yield return found; foreach (var nested in FindVisualChildren<T>(child)) yield return nested; } }
    private void ShowDatabase() { DatabasePanel.Visibility = Visibility.Visible; LoginPanel.Visibility = AppPanel.Visibility = Visibility.Collapsed; DatabaseStatus.Text = _database.GetActiveDatabase() is string a ? $"Banco ativo: {Path.GetFileName(a)}" : "Nenhum banco ativo."; }
    private void SelectDatabase_Click(object s, RoutedEventArgs e) { var list = _database.FindDatabases(); if (list.Count == 0) { MessageBox.Show("Nenhum banco encontrado."); return; } var p = new DatabasePickerWindow(list) { Owner = this }; if (p.ShowDialog() == true && p.SelectedDatabase is not null) { _database.Activate(p.SelectedDatabase); ShowLogin(); } }
    private void CreateDatabase_Click(object s, RoutedEventArgs e) { _database.CreateAndActivate(); ShowLogin(); }
    private void ImportDatabase_Click(object s, RoutedEventArgs e) { var d = new OpenFileDialog { Filter = "Backup (*.bkp15)|*.bkp15" }; if (d.ShowDialog() == true) { if (_database.GetActiveDatabase() is null || MessageBox.Show("O banco ativo será substituído após uma cópia de segurança. Continuar?", "Confirmar", MessageBoxButton.YesNo, MessageBoxImage.Warning) == MessageBoxResult.Yes) { _database.ImportAndActivate(d.FileName); ShowLogin(); } } }
    private void ShowLogin() { DatabasePanel.Visibility = AppPanel.Visibility = Visibility.Collapsed; LoginPanel.Visibility = Visibility.Visible; LoginInput.Focus(); }
    private void ReturnToDatabase_Click(object s, RoutedEventArgs e) => ShowDatabase();
    private void Login_Click(object s, RoutedEventArgs e) { _session = _database.Authenticate(LoginInput.Text, PasswordInput.Password); if (_session is null) { LoginError.Text = "Identificação ou senha inválida."; return; } _database.Log(_session, "ACESSO", "Usuário entrou no sistema."); ShowApp(); }
    private void PasswordInput_KeyDown(object s, KeyEventArgs e) { if (e.Key == Key.Enter) Login_Click(s, e); }
    private void Help_Click(object s, RoutedEventArgs e) { var active = _database.GetActiveDatabase(); var backup = _database.GetLatestAutomaticBackup(); MessageBox.Show($"Bem-vindo ao ESTATÍSTICAS 15ª BPM.\n\nBanco de dados ativo:\n{active ?? "Nenhum banco selecionado"}\n\nÚltimo backup automático:\n{backup ?? "Ainda não há backup automático"}\n\nOs backups são atualizados em segundo plano após novas inclusões e os últimos 10 dias são preservados.", "AJUDA DO SISTEMA", MessageBoxButton.OK, MessageBoxImage.Information); }
    private void ShowApp() { LoginPanel.Visibility = Visibility.Collapsed; AppPanel.Visibility = Visibility.Visible; SignedUser.Text = $"{_session!.Name}\n{_session.Role}"; SettingsButton.Visibility = _session.Role == "ADMINISTRADOR" ? Visibility.Visible : Visibility.Collapsed; if (_session.MustChangePassword) { var change = new PasswordWindow { Owner = this }; if (change.ShowDialog() == true) _database.ChangePassword(_session, change.Password!); else { MessageBox.Show("A troca da senha inicial é obrigatória."); Logout_Click(this, new RoutedEventArgs()); return; } } Navigate("DASHBOARD"); }
    private void Nav_Click(object s, RoutedEventArgs e) { var page = (string)((Button)s).Tag; if (page == "ESTATÍSTICAS") { BuildStatistics(); return; } Navigate(page); }
    private void Navigate(string page)
    {
        PageTitle.Text = page; PageHost.Children.Clear();
        if (page == "DASHBOARD") { BuildDashboard(); return; }
        if (page == "TCO") { BuildTcoList(); return; }
        if (page == "OUTRAS OCORRÊNCIAS") { BuildOtherList(); return; }
        if (page == "ESTATÍSTICAS") { BuildStatistics(); return; }
        if (page == "CONFIGURAÇÕES") { BuildSettings(); return; }
        PageHost.Children.Add(new TextBlock { Text = page switch { "ESTATÍSTICAS" => "Rankings, evolução mensal, filtros e relatórios serão apresentados aqui.", "CONFIGURAÇÕES" => "Cadastros, pendências, log de sistema, banco de dados e backups serão organizados aqui.", _ => "Bem-vindo ao sistema. Selecione TCO ou Outras Ocorrências para iniciar um cadastro." }, FontSize = 16, TextWrapping = TextWrapping.Wrap });
    }
