    private static void DrawDashboardPie(Canvas canvas, List<DashboardQuartelResumo> rows, Action<DashboardQuartelResumo> selected) { canvas.Children.Clear(); if (rows.Count == 0) { canvas.Children.Add(new TextBlock { Text = "Sem dados para formar o gráfico.", Width = 260, TextAlignment = TextAlignment.Center, Margin = new Thickness(65, 120, 0, 0) }); return; } var total = rows.Sum(x => x.Quantidade); double angle = -90; foreach (var row in rows) { var sweep = 360d * row.Quantidade / total; var top = DashboardSlice(angle, sweep, DashboardColor(row.Quartel), 0); top.Tag = row; top.MouseLeftButtonUp += (sender, _) => selected((DashboardQuartelResumo)((FrameworkElement)sender).Tag); canvas.Children.Add(top); var mid = (angle + sweep / 2) * Math.PI / 180; var text = new TextBlock { Text = $"{row.Quantidade}\n{((double)row.Quantidade / total):P0}", Foreground = System.Windows.Media.Brushes.White, FontWeight = FontWeights.Bold, FontSize = 11, TextAlignment = TextAlignment.Center, Width = 54 }; Canvas.SetLeft(text, 200 + 68 * Math.Cos(mid) - 27); Canvas.SetTop(text, 135 + 68 * Math.Sin(mid) - 14); canvas.Children.Add(text); angle += sweep; } var center = new System.Windows.Shapes.Ellipse { Width = 88, Height = 88, Fill = System.Windows.Media.Brushes.White }; Canvas.SetLeft(center, 156); Canvas.SetTop(center, 91); canvas.Children.Add(center); var label = new TextBlock { Text = $"{total}\nREGISTROS", TextAlignment = TextAlignment.Center, FontSize = 16, FontWeight = FontWeights.Bold, Foreground = new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromRgb(10, 37, 64)), Width = 100 }; Canvas.SetLeft(label, 150); Canvas.SetTop(label, 116); canvas.Children.Add(label); }
