    private static void DrawDashboardNaturePie(Canvas canvas, List<ContagemResumo> rows) { canvas.Children.Clear(); if (rows.Count == 0) { canvas.Children.Add(new TextBlock { Text = "Sem dados para formar o gráfico.", Width = 260, TextAlignment = TextAlignment.Center, Margin = new Thickness(65, 120, 0, 0) }); return; } var total = rows.Sum(x => x.Quantidade); double angle = -90; for (var index = 0; index < rows.Count; index++) { var row = rows[index]; var sweep = 360d * row.Quantidade / total; canvas.Children.Add(DashboardSlice(angle, sweep, CategoriaColor(index), 0)); var mid = (angle + sweep / 2) * Math.PI / 180; var text = new TextBlock { Text = $"{row.Quantidade}\n{((double)row.Quantidade / total):P0}", Foreground = System.Windows.Media.Brushes.White, FontWeight = FontWeights.Bold, FontSize = 11, TextAlignment = TextAlignment.Center, Width = 54 }; Canvas.SetLeft(text, 200 + 68 * Math.Cos(mid) - 27); Canvas.SetTop(text, 135 + 68 * Math.Sin(mid) - 14); canvas.Children.Add(text); angle += sweep; } var center = new System.Windows.Shapes.Ellipse { Width = 88, Height = 88, Fill = System.Windows.Media.Brushes.White }; Canvas.SetLeft(center, 156); Canvas.SetTop(center, 91); canvas.Children.Add(center); var label = new TextBlock { Text = $"{total}\nREGISTROS", TextAlignment = TextAlignment.Center, FontSize = 16, FontWeight = FontWeights.Bold, Foreground = new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromRgb(10, 37, 64)), Width = 100 }; Canvas.SetLeft(label, 150); Canvas.SetTop(label, 116); canvas.Children.Add(label); }
    private static void DrawDashboardBars(Canvas canvas, List<ContagemResumo> rows, string tipo, string escala) { canvas.Children.Clear(); var ink = new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromRgb(20, 35, 50)); canvas.Children.Add(new TextBlock { Text = $"GRÁFICO EM TORRE {escala} • {(tipo == "TCO" ? "TCOs" : "OCORRÊNCIAS")}", FontSize = 15, FontWeight = FontWeights.SemiBold, Foreground = ink, Width = 400, TextAlignment = TextAlignment.Center }); var max = Math.Max(1, rows.Count == 0 ? 0 : rows.Max(x => x.Quantidade)); const double left = 42, bottom = 250, height = 176, width = 345; var axis = new System.Windows.Shapes.Line { X1 = left, Y1 = bottom, X2 = left + width, Y2 = bottom, Stroke = ink, StrokeThickness = 1 }; canvas.Children.Add(axis); var step = width / Math.Max(rows.Count, 1); for (var i = 0; i < rows.Count; i++) { var row = rows[i]; var barHeight = height * row.Quantidade / max; var barWidth = Math.Max(4, Math.Min(38, step - 8)); var center = left + step * (i + .5); var x = center - barWidth / 2; var bar = new Border { Width = barWidth, Height = Math.Max(row.Quantidade == 0 ? 2 : barHeight, 2), Background = new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromRgb(58, 91, 113)), CornerRadius = new CornerRadius(4, 4, 0, 0) }; Canvas.SetLeft(bar, x); Canvas.SetTop(bar, bottom - bar.Height); canvas.Children.Add(bar); var labelWidth = Math.Max(24, step); var quantity = new TextBlock { Text = row.Quantidade.ToString(), FontWeight = FontWeights.SemiBold, Foreground = ink, Width = labelWidth, TextAlignment = TextAlignment.Center, FontSize = rows.Count > 15 ? 9 : 12 }; Canvas.SetLeft(quantity, center - labelWidth / 2); Canvas.SetTop(quantity, bottom - bar.Height - 21); canvas.Children.Add(quantity); var label = new TextBlock { Text = row.Item, Foreground = ink, Width = labelWidth, TextAlignment = TextAlignment.Center, FontSize = rows.Count > 15 ? 8 : 11 }; Canvas.SetLeft(label, center - labelWidth / 2); Canvas.SetTop(label, bottom + 6); canvas.Children.Add(label); } }
