    private static System.Windows.Shapes.Path DashboardSlice(double angle, double sweep, System.Windows.Media.Brush color, double depth) { const double cx = 200, cy = 135, r = 100; double R(double a) => a * Math.PI / 180; var start = new Point(cx + r * Math.Cos(R(angle)), cy + depth + r * Math.Sin(R(angle))); var end = new Point(cx + r * Math.Cos(R(angle + sweep)), cy + depth + r * Math.Sin(R(angle + sweep))); var geometry = new System.Windows.Media.StreamGeometry(); using (var ctx = geometry.Open()) { ctx.BeginFigure(new Point(cx, cy + depth), true, true); ctx.LineTo(start, true, true); ctx.ArcTo(end, new Size(r, r), 0, sweep > 180, System.Windows.Media.SweepDirection.Clockwise, true, true); } return new System.Windows.Shapes.Path { Data = geometry, Fill = color, Stroke = System.Windows.Media.Brushes.White, StrokeThickness = 1, Cursor = System.Windows.Input.Cursors.Hand }; }
