    private void ShowTco(long id)
    {
        try
        {
            var t = _database.GetTco(id); var edit = _database.GetTcoForEdit(id); if (t is null || edit is null) return;
            PageTitle.Text = "VISUALIZAR TCO"; PageHost.Children.Clear();
            PageHost.Children.Add(new TextBlock { Text = $"Nº TCO\n{t.Numero}\n\nORIGEM\n{t.Origem}\n\nQUARTEL\n{t.Quartel}\n\nDATA E HORA\n{DateTime.Parse(t.Data):dd/MM/yyyy} às {t.Hora}\n\nSTATUS\n{t.Status}\n\nNATUREZAS\n{t.Naturezas}\n\nGUARNIÇÃO\n{t.Guarnicao}\n\nOBSERVAÇÃO\n{t.Observacao}", FontSize = 16, TextWrapping = TextWrapping.Wrap });
            AddControlButtons(edit, () => OpenTcoEditor(edit), () => Inactivate("TCO", id, t.Numero));
            PageHost.Children.Add(ActionButton("VOLTAR PARA TCO", (_, _) => Navigate("TCO")));
        }
        catch (Exception ex) { MessageBox.Show(ex.Message, "Não foi possível abrir o TCO", MessageBoxButton.OK, MessageBoxImage.Warning); }
    }
