            var o = _database.GetOther(id); var edit = _database.GetOtherForEdit(id); if (o is null || edit is null) return;
            PageTitle.Text = "VISUALIZAR OCORRÊNCIA"; PageHost.Children.Clear();
            PageHost.Children.Add(new TextBlock { Text = $"Nº DA OCORRÊNCIA / B.O.\n{o.Numero}\n\nQUARTEL\n{o.Quartel}\n\nDATA E HORA\n{DateTime.Parse(o.Data):dd/MM/yyyy} às {o.Hora}\n\nSTATUS\n{o.Status}\n\nNATUREZA\n{o.Natureza}\n\nGUARNIÇÃO\n{o.Guarnicao}\n\nMATERIAL APREENDIDO\n{o.Material}\n\nOBSERVAÇÃO\n{o.Observacao}", FontSize = 16, TextWrapping = TextWrapping.Wrap });
            AddControlButtons(edit, () => OpenOtherEditor(edit), () => Inactivate("OUTRA OCORRÊNCIA", id, o.Numero));
            PageHost.Children.Add(ActionButton("VOLTAR PARA OCORRÊNCIAS", (_, _) => Navigate("OUTRAS OCORRÊNCIAS")));
        }
        catch (Exception ex) { MessageBox.Show(ex.Message, "Não foi possível abrir a ocorrência", MessageBoxButton.OK, MessageBoxImage.Warning); }
    }
