    private static DataGridTextColumn TextColumn(string header, string path, object width) => new() { Header = header, Binding = new Binding(path), Width = width switch { int n => new DataGridLength(n), double n => new DataGridLength(n), DataGridLength n => n, _ => new DataGridLength(100) } };
    private static DataGridTemplateColumn TableButton(string text, RoutedEventHandler action) { var factory = new FrameworkElementFactory(typeof(Button)); factory.SetValue(Button.ContentProperty, text); factory.SetBinding(FrameworkElement.TagProperty, new Binding("Id")); factory.AddHandler(Button.ClickEvent, action); return new DataGridTemplateColumn { Header = "Ação", CellTemplate = new DataTemplate { VisualTree = factory }, Width = 105 }; }
    private static Button ActionButton(string text, RoutedEventHandler action) { var b = new Button { Content = text, HorizontalAlignment = HorizontalAlignment.Left }; b.Click += action; return b; }
    private static Border RecordFrame(DataGrid grid) => new() { Background = System.Windows.Media.Brushes.White, BorderBrush = new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromRgb(218, 225, 230)), BorderThickness = new Thickness(1), CornerRadius = new CornerRadius(8), Padding = new Thickness(1), Child = grid };
    private void AddControlButtons(TcoEdicao record, Action edit, Action inactivate) { if (record.Status == "ATIVO" && _database.CanEdit(record.CriadoEm, record.CriadoPor, _session!)) PageHost.Children.Add(ActionButton("EDITAR REGISTRO", (_, _) => edit())); if (_session!.Role == "ADMINISTRADOR" && record.Status == "ATIVO") PageHost.Children.Add(ActionButton("INATIVAR REGISTRO", (_, _) => inactivate())); if (_session.Role == "ADMINISTRADOR" && record.Status == "INATIVO") { PageHost.Children.Add(ActionButton("REATIVAR TCO", (_, _) => { _database.ReactivateRegistro("TCO", record.Id, _session); Navigate("TCO"); })); PageHost.Children.Add(ActionButton("EXCLUIR TCO DEFINITIVAMENTE", (_, _) => { if (MessageBox.Show("Excluir definitivamente este TCO inativo? Esta ação remove a guarnição e todas as pontuações vinculadas.", "Confirmar exclusão", MessageBoxButton.YesNo, MessageBoxImage.Warning) == MessageBoxResult.Yes) { _database.DeleteTco(record.Id, _session); Navigate("TCO"); } })); } }
    private void AddControlButtons(OcorrenciaEdicao record, Action edit, Action inactivate) { if (record.Status == "ATIVO" && _database.CanEdit(record.CriadoEm, record.CriadoPor, _session!)) PageHost.Children.Add(ActionButton("EDITAR REGISTRO", (_, _) => edit())); if (record.Status == "ATIVO" && _session!.Role == "ADMINISTRADOR") PageHost.Children.Add(ActionButton("INATIVAR REGISTRO", (_, _) => inactivate())); }
    private void Inactivate(string modulo, long id, string numero) { var dialog = new InactivationWindow { Owner = this }; if (dialog.ShowDialog() == true && dialog.Reason is not null) { _database.Inactivate(modulo, id, dialog.Reason, _session!); MessageBox.Show($"Registro {numero} inativado. Os dados foram preservados no histórico."); Navigate(modulo == "TCO" ? "TCO" : "OUTRAS OCORRÊNCIAS"); } }
    private void BuildSettings() { PageHost.Children.Add(new TextBlock { Text = "Administração do sistema", FontSize = 18, FontWeight = FontWeights.SemiBold, Margin = new Thickness(0, 0, 0, 14) }); PageHost.Children.Add(ActionButton("USUÁRIOS E POLICIAIS", (_, _) => BuildUsers())); PageHost.Children.Add(ActionButton("QUARTEIS", (_, _) => BuildQuarteis())); PageHost.Children.Add(ActionButton("NATUREZAS", (_, _) => BuildNaturezas())); PageHost.Children.Add(ActionButton("BANCO DE DADOS E BACKUPS", (_, _) => BuildDatabaseManagement())); PageHost.Children.Add(ActionButton("ALTERAR MINHA SENHA", (_, _) => ChangeMyPassword())); PageHost.Children.Add(ActionButton("LOGS DO SISTEMA", (_, _) => BuildLogs())); }
    private void BuildUsers()
    {
        PageTitle.Text = "USUÁRIOS E POLICIAIS";
        PageHost.Children.Clear();

        var login = Field("RGPM");
        var nome = Field("Nome ou QRA");
        var posto = new ComboBox
        {
            ItemsSource = new[] { "SUBTENENTE", "1º SARGENTO", "2º SARGENTO", "3º SARGENTO", "CABO", "SOLDADO" },
            SelectedItem = "SOLDADO",
            MinWidth = 260
        };
        var quartel = new ComboBox
        {
            ItemsSource = _database.GetQuarteis(),
            SelectedItem = "15º BPM - SEDE",
            MinWidth = 260
        };
        var funcao = new ComboBox
        {
            ItemsSource = new[] { "OPERADOR", "ADMINISTRADOR" },
            SelectedItem = "OPERADOR",
            MinWidth = 260
        };

        Add("RGPM", login);
        Add("Nome / QRA", nome);
        Add("Posto ou graduação", posto);
        Add("Quartel", quartel);
        Add("Função", funcao);
        PageHost.Children.Add(ActionButton("CADASTRAR USUÁRIO", (_, _) =>
        {
            try
            {
                if (string.IsNullOrWhiteSpace(login.Text) || string.IsNullOrWhiteSpace(nome.Text))
                    throw new InvalidOperationException("Informe RGPM e nome.");

                _database.CreateUsuario(login.Text, nome.Text, (string)posto.SelectedItem, (string)quartel.SelectedItem, (string)funcao.SelectedItem, _session!);
                MessageBox.Show("Usuário cadastrado. A senha inicial é 15bpm e deverá ser alterada no primeiro acesso.");
                BuildUsers();
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message, "Não foi possível salvar", MessageBoxButton.OK, MessageBoxImage.Warning);
            }
        }));

        PageHost.Children.Add(new TextBlock { Text = "Usuários cadastrados", FontWeight = FontWeights.SemiBold, Margin = new Thickness(0, 20, 0, 6) });
        var grid = new DataGrid { ItemsSource = _database.GetUsuarios(), AutoGenerateColumns = false, IsReadOnly = true, CanUserAddRows = false, MinHeight = 260 };
        grid.Columns.Add(TextColumn("Nome", "Nome", new DataGridLength(1, DataGridLengthUnitType.Star)));
        grid.Columns.Add(TextColumn("Posto", "Posto", 120));
        grid.Columns.Add(TextColumn("RGPM", "Login", 100));
        grid.Columns.Add(TextColumn("Quartel", "Quartel", 140));
        grid.Columns.Add(TextColumn("Situação", "Situacao", 90));
        grid.Columns.Add(TableButton("EDITAR", EditUser_Click));
        grid.Columns.Add(TableButton("ATIVAR / INATIVAR", InactivateUser_Click));
        grid.Columns.Add(TableButton("EXCLUIR", ExcludeUser_Click));
        PageHost.Children.Add(RecordFrame(grid));
    }
    private void BuildQuarteis(QuartelResumo? editing = null) { PageTitle.Text = editing is null ? "QUARTEIS" : "EDITAR QUARTEL"; PageHost.Children.Clear(); var name = Field("Nome do quartel"); name.Text = editing?.Nome ?? ""; Add(editing is null ? "Novo quartel" : "Nome do quartel", name); PageHost.Children.Add(ActionButton(editing is null ? "CADASTRAR QUARTEL" : "SALVAR ALTERAÇÕES", (_, _) => { try { if (string.IsNullOrWhiteSpace(name.Text)) throw new InvalidOperationException("Informe o nome do quartel."); if (editing is null) _database.CreateQuartel(name.Text, _session!); else _database.UpdateQuartel(editing, name.Text, _session!); BuildQuarteis(); } catch (Exception ex) { MessageBox.Show(ex.Message, "Não foi possível salvar", MessageBoxButton.OK, MessageBoxImage.Warning); } })); if (editing is not null) { PageHost.Children.Add(ActionButton("VOLTAR", (_, _) => BuildQuarteis())); return; } var grid = new DataGrid { ItemsSource = _database.GetAllQuarteis(), AutoGenerateColumns = false, IsReadOnly = true, CanUserAddRows = false, MinHeight = 260, Margin = new Thickness(0, 20, 0, 0) }; grid.Columns.Add(TextColumn("Quartel", "Nome", new DataGridLength(1, DataGridLengthUnitType.Star))); grid.Columns.Add(TextColumn("Situação", "Situacao", 110)); grid.Columns.Add(TableButton("OPERADORES", ViewQuartelUsers_Click)); grid.Columns.Add(TableButton("EDITAR", EditQuartel_Click)); grid.Columns.Add(TableButton("INATIVAR", InactivateQuartel_Click)); grid.Columns.Add(TableButton("EXCLUIR", DeleteQuartel_Click)); PageHost.Children.Add(RecordFrame(grid)); }
    private void BuildNaturezas(NaturezaResumo? editing = null) { PageTitle.Text = editing is null ? "NATUREZAS" : "EDITAR NATUREZA"; PageHost.Children.Clear(); var modulo = new ComboBox { ItemsSource = new[] { "TCO", "CRIMES" }, SelectedItem = editing?.Modulo ?? "TCO", MinWidth = 180 }; var artigo = Field("Ex.: Art. 147"); artigo.Text = editing?.Artigo ?? ""; var descricao = Field("Descrição da natureza"); descricao.Text = editing?.Descricao ?? ""; Add("Módulo", modulo); Add("Artigo (quando houver)", artigo); Add("Descrição", descricao); PageHost.Children.Add(ActionButton(editing is null ? "CADASTRAR NATUREZA" : "SALVAR ALTERAÇÕES", (_, _) => { try { if (string.IsNullOrWhiteSpace(descricao.Text)) throw new InvalidOperationException("Informe a descrição da natureza."); if (editing is null) _database.CreateNatureza((string)modulo.SelectedItem, artigo.Text, descricao.Text, _session!); else _database.UpdateNatureza(editing, (string)modulo.SelectedItem, artigo.Text, descricao.Text, _session!); BuildNaturezas(); } catch (Exception ex) { MessageBox.Show(ex.Message, "Não foi possível salvar", MessageBoxButton.OK, MessageBoxImage.Warning); } })); if (editing is not null) { PageHost.Children.Add(ActionButton("VOLTAR", (_, _) => BuildNaturezas())); return; } var grid = new DataGrid { ItemsSource = _database.GetAllNaturezas(), AutoGenerateColumns = false, IsReadOnly = true, CanUserAddRows = false, MinHeight = 260, Margin = new Thickness(0, 20, 0, 0) }; grid.Columns.Add(TextColumn("Módulo", "Modulo", 100)); grid.Columns.Add(TextColumn("Artigo", "Artigo", 120)); grid.Columns.Add(TextColumn("Descrição", "Descricao", new DataGridLength(1, DataGridLengthUnitType.Star))); grid.Columns.Add(TextColumn("Situação", "Situacao", 100)); grid.Columns.Add(TableButton("EDITAR", EditNatureza_Click)); grid.Columns.Add(TableButton("INATIVAR", InactivateNatureza_Click)); grid.Columns.Add(TableButton("EXCLUIR", ExcludeNatureza_Click)); PageHost.Children.Add(RecordFrame(grid)); }
    private void EditUser_Click(object sender, RoutedEventArgs e) { if (((FrameworkElement)sender).DataContext is UsuarioResumo u) BuildUserEdit(u); }
