    private void ExcludeUser_Click(object sender, RoutedEventArgs e) { if (((FrameworkElement)sender).DataContext is UsuarioResumo u && MessageBox.Show($"Excluir {u.Nome} dos novos cadastros e acessos? Os registros anteriores serão preservados.", "Confirmar exclusão", MessageBoxButton.YesNo, MessageBoxImage.Warning) == MessageBoxResult.Yes) { _database.ExcludeUsuario(u.Id, _session!); BuildUsers(); } }
