    private void BuildLogs() { PageTitle.Text = "LOGS DO SISTEMA"; PageHost.Children.Clear(); PageHost.Children.Add(new TextBlock { Text = "Últimas 100 ações registradas", Margin = new Thickness(0, 0, 0, 10) }); if (_session!.Login == "admin") PageHost.Children.Add(ActionButton("APAGAR TODOS OS LOGS", (_, _) => { if (MessageBox.Show("Apagar definitivamente todos os logs do sistema?", "Confirmar", MessageBoxButton.YesNo, MessageBoxImage.Warning) == MessageBoxResult.Yes) { _database.ClearLogs(_session); BuildLogs(); } })); var grid = new DataGrid { ItemsSource = _database.GetLogs(), AutoGenerateColumns = false, IsReadOnly = true, CanUserAddRows = false, MinHeight = 400 }; grid.Columns.Add(TextColumn("Data e hora", "DataHora", 190)); grid.Columns.Add(TextColumn("Usuário", "Usuario", 110)); grid.Columns.Add(TextColumn("Registro", "Registro", 130)); grid.Columns.Add(TextColumn("Descrição", "Descricao", new DataGridLength(1, DataGridLengthUnitType.Star))); PageHost.Children.Add(RecordFrame(grid)); }
