    private void ChangeMyPassword() { var dialog = new PasswordWindow { Owner = this }; if (dialog.ShowDialog() == true) { try { _database.ChangePassword(_session!, dialog.Password!); MessageBox.Show("Senha alterada com sucesso."); } catch (Exception ex) { MessageBox.Show(ex.Message, "Não foi possível alterar", MessageBoxButton.OK, MessageBoxImage.Warning); } } }
    private void BuildStatistics()
    {
        PageTitle.Text = "RANKING POLICIAL";
        PageHost.Children.Clear();
        var inicio = new DatePicker { SelectedDate = new DateTime(DateTime.Today.Year, 1, 1), Width = 135 }; var fim = new DatePicker { SelectedDate = DateTime.Today, Width = 135 };
        var quartel = new ComboBox { ItemsSource = new[] { "TODOS" }.Concat(_database.GetQuarteis()).ToArray(), SelectedIndex = 0, Width = 160 };
        var tipo = new ComboBox { ItemsSource = new[] { "TCO", "OUTRAS OCORRÊNCIAS GERAIS" }, SelectedIndex = 0, Width = 190 }; var natureza = new ComboBox { Width = 220 };
        void RefreshNaturezas() { natureza.ItemsSource = new[] { "TODAS" }.Concat(_database.GetNaturezas((string?)tipo.SelectedItem == "TCO" ? "TCO" : "CRIMES").Select(x => x.Descricao)).ToArray(); natureza.SelectedIndex = 0; }
        tipo.SelectionChanged += (_, _) => RefreshNaturezas(); RefreshNaturezas();
        var filters = new WrapPanel { Margin = new Thickness(0, 0, 0, 10) }; void FieldFilter(string label, UIElement control) { filters.Children.Add(new StackPanel { Children = { new TextBlock { Text = label, FontWeight = FontWeights.SemiBold }, control }, Margin = new Thickness(0, 0, 10, 0) }); }
        FieldFilter("INÍCIO", inicio); FieldFilter("FIM", fim); FieldFilter("QUARTEL", quartel); FieldFilter("TIPO DE REGISTRO", tipo); FieldFilter("NATUREZA", natureza); PageHost.Children.Add(filters);
        var quick = new WrapPanel { Width = 640 }; var content = new StackPanel(); var reportText = ""; var reportRows = new List<string[]>();
        Button ReportButton(string title, System.Windows.Media.Brush color, double width, RoutedEventHandler click) { var b = new Button { Content = title, Width = width, Padding = new Thickness(18, 12, 18, 12), Margin = new Thickness(5), Background = color, Foreground = System.Windows.Media.Brushes.White, FontWeight = FontWeights.SemiBold }; b.Click += click; return b; }
        void Load() { content.Children.Clear(); var selectedNature = (string?)natureza.SelectedItem == "TODAS" ? null : (string?)natureza.SelectedItem; var selectedQuartel = (string?)quartel.SelectedItem == "TODOS" ? null : (string?)quartel.SelectedItem; var result = _database.GetEstatisticas(inicio.SelectedDate ?? DateTime.Today, fim.SelectedDate ?? DateTime.Today, selectedQuartel, (string)tipo.SelectedItem, selectedNature); var ranking = result.Ranking.Select((x, index) => new RankingLinha($"{index + 1}°", x.Quantidade, x.Item)).ToList(); reportRows = ranking.Select(x => new[] { x.Posicao, x.Quantidade.ToString(), x.Operador }).ToList(); reportText = $"ESTATÍSTICAS 15ª BPM\nPeríodo: {inicio.SelectedDate:dd/MM/yyyy} a {fim.SelectedDate:dd/MM/yyyy}\nQuartel: {quartel.SelectedItem}\nTipo: {tipo.SelectedItem} — Natureza: {selectedNature ?? "Todas"}"; content.Children.Add(new TextBlock { Text = $"RANKING POLICIAL — {inicio.SelectedDate:dd/MM/yyyy} a {fim.SelectedDate:dd/MM/yyyy}\nQuartel: {quartel.SelectedItem}\nTipo: {tipo.SelectedItem} — Natureza: {selectedNature ?? "Todas"}", FontSize = 18, FontWeight = FontWeights.SemiBold, Margin = new Thickness(0, 18, 0, 12) }); content.Children.Add(new TextBlock { Text = "RANKING DE OPERADORES", FontSize = 16, FontWeight = FontWeights.SemiBold, Margin = new Thickness(0, 0, 0, 6) }); var grid = new DataGrid { ItemsSource = ranking, AutoGenerateColumns = false, IsReadOnly = true, CanUserAddRows = false, Height = 500 }; grid.Columns.Add(TextColumn("Posição", "Posicao", 90)); grid.Columns.Add(TextColumn("Quantidade de TCOs", "Quantidade", 145)); grid.Columns.Add(TextColumn("Posto/Patente e nome do operador", "Operador", new DataGridLength(1, DataGridLengthUnitType.Star))); content.Children.Add(RecordFrame(grid)); content.Children.Add(ActionButton("VISUALIZAR TCOs / B.O.s DO OPERADOR SELECIONADO", (_, _) => { if (grid.SelectedItem is RankingLinha row) { var p = _database.GetPoliciais(selectedQuartel).FirstOrDefault(x => row.Operador == $"{x.Posto} PM {x.Qra}"); if (p is not null) new ParticipationsWindow(p, _database.GetParticipacoes(p.Id, inicio.SelectedDate ?? DateTime.Today, fim.SelectedDate ?? DateTime.Today, selectedQuartel, (string)tipo.SelectedItem, selectedNature)) { Owner = this }.ShowDialog(); } else MessageBox.Show("Selecione um operador no ranking."); })); }
        void Period(string label, Func<(DateTime Start, DateTime End)> get) => quick.Children.Add(ReportButton(label, new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromRgb(73, 101, 120)), 150, (_, _) => { var d = get(); inicio.SelectedDate = d.Start; fim.SelectedDate = d.End; Load(); })); Period("HOJE", () => (DateTime.Today, DateTime.Today)); Period("ESTA SEMANA", () => (DateTime.Today.AddDays(-(int)DateTime.Today.DayOfWeek), DateTime.Today)); Period("ESTE MÊS", () => (new DateTime(DateTime.Today.Year, DateTime.Today.Month, 1), DateTime.Today)); Period("ESTE ANO", () => (new DateTime(DateTime.Today.Year, 1, 1), DateTime.Today));
        PageHost.Children.Add(quick); var actions = new WrapPanel { Width = 640 }; actions.Children.Add(ReportButton("ATUALIZAR ESTATÍSTICAS", new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromRgb(58, 91, 113)), 310, (_, _) => Load())); actions.Children.Add(ReportButton("PRÉ-VISUALIZAR E IMPRIMIR", new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromRgb(161, 125, 62)), 310, (_, _) => new ReportPreviewWindow(reportText, new[] { "POSIÇÃO", "QUANTIDADE DE TCOs", "POSTO/PATENTE E OPERADOR" }, reportRows) { Owner = this }.ShowDialog())); PageHost.Children.Add(actions); PageHost.Children.Add(content); inicio.SelectedDateChanged += (_, _) => Load(); fim.SelectedDateChanged += (_, _) => Load(); quartel.SelectionChanged += (_, _) => Load(); tipo.SelectionChanged += (_, _) => Load(); natureza.SelectionChanged += (_, _) => Load(); Load();
    }
    private void BuildDatabaseManagement()
    {
        PageTitle.Text = "BANCO DE DADOS E BACKUPS"; PageHost.Children.Clear();
        var storage = _database.GetStorageResumo(); var usedPercent = storage.Total == 0 ? 0 : (double)storage.Usado / storage.Total; var bar = new Grid { Height = 20, Width = 620, Margin = new Thickness(0, 5, 0, 14), ClipToBounds = true }; bar.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(Math.Max(usedPercent, 0.002), GridUnitType.Star) }); bar.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(Math.Max(1 - usedPercent, 0.002), GridUnitType.Star) }); var used = new Border { Background = new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromRgb(176, 60, 60)) }; var available = new Border { Background = new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromRgb(68, 138, 88)) }; Grid.SetColumn(available, 1); bar.Children.Add(used); bar.Children.Add(available); PageHost.Children.Add(new TextBlock { Text = "ESPAÇO DISPONÍVEL NO COMPUTADOR", FontSize = 16, FontWeight = FontWeights.SemiBold }); PageHost.Children.Add(new TextBlock { Text = $"Usado: {FormatBytes(storage.Usado)}     Disponível: {FormatBytes(storage.Disponivel)}     Total: {FormatBytes(storage.Total)}", Margin = new Thickness(0, 4, 0, 0) }); PageHost.Children.Add(bar);
        var active = _database.GetActiveDatabase(); PageHost.Children.Add(new TextBlock { Text = $"Banco ativo: {Path.GetFileName(active ?? "")} ({FormatBytes(active is null ? 0 : new FileInfo(active).Length)})", FontSize = 16, FontWeight = FontWeights.SemiBold, Margin = new Thickness(0, 0, 0, 12) }); PageHost.Children.Add(ActionButton("EXPORTAR BACKUP .BKP15", (_, _) => { var d = new SaveFileDialog { Filter = "Backup ESTATÍSTICAS 15ª BPM (*.bkp15)|*.bkp15", FileName = $"Backup_15BPM_{DateTime.Now:yyyy-MM-dd_HHmm}.bkp15" }; if (d.ShowDialog() == true) { _database.Export(d.FileName); MessageBox.Show("Backup exportado com sucesso."); } })); PageHost.Children.Add(ActionButton("IMPORTAR BACKUP .BKP15", (_, _) => ImportDatabase_Click(this, new RoutedEventArgs()))); PageHost.Children.Add(ActionButton("SELECIONAR OUTRO BANCO", (_, _) => { Logout_Click(this, new RoutedEventArgs()); ShowDatabase(); })); PageHost.Children.Add(new TextBlock { Text = "Bancos disponíveis", FontWeight = FontWeights.SemiBold, Margin = new Thickness(0, 20, 0, 6) });
        var list = new ListBox { ItemsSource = _database.FindDatabases().Select(path => new BancoDisponivel(Path.GetFileName(path), path)).ToList(), DisplayMemberPath = "Nome", Height = 230, MinWidth = 620 }; PageHost.Children.Add(list); PageHost.Children.Add(ActionButton("EXCLUIR BANCO SELECIONADO", (_, _) => { if (list.SelectedItem is not BancoDisponivel selected) { MessageBox.Show("Selecione um banco na lista."); return; } if (MessageBox.Show($"Será gerado um backup de segurança do banco {selected.Nome}. Deseja continuar?", "1ª confirmação", MessageBoxButton.YesNo, MessageBoxImage.Warning) != MessageBoxResult.Yes) return; try { var backup = _database.CreateDeletionBackup(selected.Caminho); if (MessageBox.Show($"Backup criado em {Path.GetFileName(backup)}.\n\nExcluir definitivamente o banco {selected.Nome}? Esta ação não poderá ser desfeita.", "2ª confirmação", MessageBoxButton.YesNo, MessageBoxImage.Warning) != MessageBoxResult.Yes) return; _database.DeleteDatabasePermanently(selected.Caminho); MessageBox.Show("Banco excluído definitivamente. O backup de segurança foi preservado."); BuildDatabaseManagement(); } catch (Exception ex) { MessageBox.Show(ex.Message, "Não foi possível excluir", MessageBoxButton.OK, MessageBoxImage.Warning); } })); PageHost.Children.Add(new TextBlock { Text = "A exclusão exige duas confirmações. O banco ativo não pode ser excluído; selecione outro banco antes de prosseguir.", TextWrapping = TextWrapping.Wrap, Foreground = System.Windows.Media.Brushes.DimGray, Margin = new Thickness(0, 12, 0, 0) });
    }
    private static string FormatBytes(long bytes) => bytes >= 1024L * 1024 * 1024 ? $"{bytes / (1024d * 1024 * 1024):0.00} GB" : bytes >= 1024L * 1024 ? $"{bytes / (1024d * 1024):0.00} MB" : $"{bytes / 1024d:0.00} KB";
    private void BuildTcoForm(TcoEdicao? editing = null)
    {
        PageHost.Children.Add(new TextBlock { Text = "Preencha os dados e confirme a finalização para contabilizar o TCO.", Margin = new Thickness(0, 0, 0, 18) });
        var origem = new ComboBox { ItemsSource = new[] { "TCO MANUAL", "TCO TALONÁRIO" }, SelectedItem = editing?.Origem == "TCO NO TALONÁRIO" ? "TCO TALONÁRIO" : editing?.Origem ?? "TCO MANUAL", MinWidth = 260 };
        var isLegacy = editing is not null && !System.Text.RegularExpressions.Regex.IsMatch(editing.Numero, @"^(?:\d{1,8}/15BPM/\d{4}|\d{4}\.\d{1,8})$");
        var numero = Field(isLegacy ? "Nº TCO (registro anterior)" : "Número do TCO (até 8 dígitos)");
        var numeroCompleto = new TextBox { IsReadOnly = true, MinWidth = 260, Background = System.Windows.Media.Brushes.WhiteSmoke, Foreground = System.Windows.Media.Brushes.DimGray };
        if (isLegacy) numero.Text = editing!.Numero;
        else numero.Text = editing is null ? "" : ((string?)origem.SelectedItem == "TCO TALONÁRIO" ? editing.Numero.Split('.')[1] : editing.Numero.Split('/')[0]);
        string NumeroParaSalvar() => isLegacy ? numero.Text.Trim() : numeroCompleto.Text;
        void AtualizarNumero()
        {
            if (isLegacy) return;
            var digitos = new string(numero.Text.Where(char.IsDigit).Take(8).ToArray());
            if (numero.Text != digitos) { numero.Text = digitos; numero.CaretIndex = digitos.Length; }
            var talonario = (string?)origem.SelectedItem == "TCO TALONÁRIO";
            numeroCompleto.Text = string.IsNullOrEmpty(digitos) ? (talonario ? $"{DateTime.Today:yyyy}.__" : $"__/15BPM/{DateTime.Today:yyyy}") : (talonario ? $"{DateTime.Today:yyyy}.{digitos}" : $"{digitos}/15BPM/{DateTime.Today:yyyy}");
        }
        numero.TextChanged += (_, _) => AtualizarNumero();
        origem.SelectionChanged += (_, _) => AtualizarNumero();
        AtualizarNumero();
        var numeroBox = new StackPanel(); numeroBox.Children.Add(numero);
        if (!isLegacy) { numeroBox.Children.Add(new TextBlock { Text = "NÚMERO COMPLETO", FontWeight = FontWeights.SemiBold, Margin = new Thickness(0, 8, 0, 2) }); numeroBox.Children.Add(numeroCompleto); }
        var quartel = new ComboBox { ItemsSource = _database.GetQuarteis(), SelectedItem = editing?.Quartel ?? "15º BPM - SEDE", MinWidth = 260 };
        var data = new DatePicker { SelectedDate = editing?.Data ?? DateTime.Today, Width = 160 }; var hora = TimeSelector(editing?.Hora); var naturezas = NaturezaSelector("TCO", true, editing?.Naturezas); var guarnicao = GuarnicaoSelector(quartel, editing?.Guarnicao); var observacao = new TextBox { AcceptsReturn = true, TextWrapping = TextWrapping.Wrap, Height = 90, MaxLength = 500, Text = editing?.Observacao ?? "" };
        Add("Origem", origem); Add(isLegacy ? "Nº TCO" : "Nº TCO — informe somente os números", numeroBox); Add("Quartel responsável", quartel); Add("Data e hora do fato", SideBySide(data, hora)); Add("Natureza(s) — selecione uma ou mais", naturezas); Add("Guarnição — selecione um ou mais policiais", guarnicao); Add("Observação (até 500 caracteres)", observacao);
        var save = new Button { Content = editing is null ? "CONFERIR E FINALIZAR TCO" : "CONFERIR E SALVAR ALTERAÇÕES", HorizontalAlignment = HorizontalAlignment.Left, Margin = new Thickness(0, 16, 0, 0) }; save.Click += (_, _) => { try { var numeroSalvo = NumeroParaSalvar(); var selecionadas = SelectedNaturezas(naturezas); var equipe = SelectedPoliciais(guarnicao); if (string.IsNullOrWhiteSpace(numeroSalvo) || (!isLegacy && string.IsNullOrWhiteSpace(numero.Text)) || selecionadas.Length == 0 || equipe.Length == 0) throw new InvalidOperationException("Informe até 8 dígitos do TCO, selecione natureza(s) e a guarnição."); var resumo = $"ORIGEM\n{origem.SelectedItem}\n\nNº TCO\n{numeroSalvo}\n\nQUARTEL\n{quartel.SelectedItem}\n\nDATA E HORA DO FATO\n{data.SelectedDate:dd/MM/yyyy} às {ReadTime(hora)}\n\nNATUREZAS\n{string.Join("\n", selecionadas.Select(x => x.Exibicao))}\n\nGUARNIÇÃO\n{string.Join("\n", equipe.Select(x => x.Exibicao))}\n\nOBSERVAÇÃO\n{observacao.Text}"; if (new SummaryWindow("RESUMO DO TCO", resumo, editing is null ? "FINALIZAR TCO" : "SALVAR ALTERAÇÕES") { Owner = this }.ShowDialog() == true) { if (editing is null) _database.CreateTco(numeroSalvo, (string)quartel.SelectedItem, (string)origem.SelectedItem, data.SelectedDate ?? DateTime.Today, ReadTime(hora), selecionadas, equipe, observacao.Text, _session!); else _database.UpdateTco(editing, numeroSalvo, (string)quartel.SelectedItem, (string)origem.SelectedItem, data.SelectedDate ?? DateTime.Today, ReadTime(hora), selecionadas, equipe, observacao.Text, _session!); MessageBox.Show($"TCO {numeroSalvo} salvo com sucesso."); Navigate("TCO"); } } catch (Exception ex) { MessageBox.Show(ex.Message, "Não foi possível salvar", MessageBoxButton.OK, MessageBoxImage.Warning); } }; PageHost.Children.Add(save);
    }
    private void BuildOtherForm(OcorrenciaEdicao? editing = null)
    {
        PageHost.Children.Add(new TextBlock { Text = "Cadastre a ocorrência operacional. Registros ativos serão considerados nas estatísticas.", Margin = new Thickness(0, 0, 0, 18) });
        var numero = Field("Ex.: 2026.123456"); numero.Text = editing?.Numero ?? ""; var quartel = new ComboBox { ItemsSource = _database.GetQuarteis(), SelectedItem = editing?.Quartel ?? "SEDE", MinWidth = 260 }; var data = new DatePicker { SelectedDate = editing?.Data ?? DateTime.Today, Width = 160 }; var hora = TimeSelector(editing?.Hora); var natureza = NaturezaSelector("CRIMES", false, editing is null ? null : _database.GetNaturezas("CRIMES").Where(x => x.Descricao == editing.Natureza)); var guarnicao = GuarnicaoSelector(quartel, editing?.Guarnicao); var material = new TextBox { AcceptsReturn = true, TextWrapping = TextWrapping.Wrap, Height = 80, Text = editing?.Material ?? "" }; var obs = new TextBox { AcceptsReturn = true, TextWrapping = TextWrapping.Wrap, Height = 80, MaxLength = 500, Text = editing?.Observacao ?? "" };
        Add("Nº da ocorrência / B.O. — Ex.: 2026.123456", numero); Add("Quartel responsável", quartel); Add("Data e hora do fato", SideBySide(data, hora)); Add("Natureza", natureza); Add("Guarnição — selecione um ou mais policiais", guarnicao); Add("Material apreendido", material); Add("Observação (até 500 caracteres)", obs);
        var save = new Button { Content = editing is null ? "CONFERIR E FINALIZAR OCORRÊNCIA" : "CONFERIR E SALVAR ALTERAÇÕES", HorizontalAlignment = HorizontalAlignment.Left, Margin = new Thickness(0, 16, 0, 0) }; save.Click += (_, _) => { try { var escolha = SelectedNaturezas(natureza); var equipe = SelectedPoliciais(guarnicao); if (string.IsNullOrWhiteSpace(numero.Text) || escolha.Length == 0 || equipe.Length == 0) throw new InvalidOperationException("Preencha o número, selecione uma natureza e a guarnição."); var resumo = $"Nº DA OCORRÊNCIA / B.O.\n{numero.Text}\n\nQUARTEL\n{quartel.SelectedItem}\n\nDATA E HORA DO FATO\n{data.SelectedDate:dd/MM/yyyy} às {ReadTime(hora)}\n\nNATUREZA\n{escolha[0].Exibicao}\n\nGUARNIÇÃO\n{string.Join("\n", equipe.Select(x => x.Exibicao))}\n\nMATERIAL APREENDIDO\n{material.Text}\n\nOBSERVAÇÃO\n{obs.Text}"; if (new SummaryWindow("RESUMO DA OCORRÊNCIA", resumo, editing is null ? "FINALIZAR OCORRÊNCIA" : "SALVAR ALTERAÇÕES") { Owner = this }.ShowDialog() == true) { if (editing is null) _database.CreateOther(numero.Text, (string)quartel.SelectedItem, data.SelectedDate ?? DateTime.Today, ReadTime(hora), escolha[0].Descricao, equipe, material.Text, obs.Text, _session!); else _database.UpdateOther(editing, numero.Text, (string)quartel.SelectedItem, data.SelectedDate ?? DateTime.Today, ReadTime(hora), escolha[0].Descricao, equipe, material.Text, obs.Text, _session!); MessageBox.Show($"Ocorrência {numero.Text} salva com sucesso."); Navigate("OUTRAS OCORRÊNCIAS"); } } catch (Exception ex) { MessageBox.Show(ex.Message, "Não foi possível salvar", MessageBoxButton.OK, MessageBoxImage.Warning); } }; PageHost.Children.Add(save);
    }
    private TextBox Field(string placeholder) => new() { MinWidth = 260, Height = 32, ToolTip = placeholder };
    private StackPanel NaturezaSelector(string modulo, bool multiple, IEnumerable<Natureza>? initial = null) { var search = new TextBox { Height = 30, MinWidth = 560, ToolTip = "Pesquisar por artigo ou descrição" }; var list = new ListBox { DisplayMemberPath = "Exibicao", SelectionMode = multiple ? SelectionMode.Multiple : SelectionMode.Single, Height = 250, MinWidth = 560, Foreground = System.Windows.Media.Brushes.Black, Background = System.Windows.Media.Brushes.White, BorderBrush = System.Windows.Media.Brushes.SlateGray }; var selected = (initial ?? Enumerable.Empty<Natureza>()).Select(x => x.Id).ToHashSet(); ScrollViewer.SetVerticalScrollBarVisibility(list, ScrollBarVisibility.Auto); void Refresh() { var q = search.Text.Trim(); var data = _database.GetNaturezas(modulo).Where(x => string.IsNullOrWhiteSpace(q) || x.Exibicao.Contains(q, StringComparison.OrdinalIgnoreCase)).ToList(); list.ItemsSource = data; foreach (var item in data.Where(x => selected.Contains(x.Id))) list.SelectedItems.Add(item); } search.TextChanged += (_, _) => Refresh(); Refresh(); var p = new StackPanel { Tag = list, HorizontalAlignment = HorizontalAlignment.Stretch }; p.Children.Add(search); p.Children.Add(list); return p; }
    private StackPanel GuarnicaoSelector(ComboBox quartel, IEnumerable<Policial>? initial = null) { var search = new TextBox { Height = 30, MinWidth = 300, ToolTip = "Pesquisar por QRA ou RGPM" }; var available = new ListBox { DisplayMemberPath = "Exibicao", SelectionMode = SelectionMode.Multiple, Height = 250, MinWidth = 300, Foreground = System.Windows.Media.Brushes.Black, Background = System.Windows.Media.Brushes.White, BorderBrush = System.Windows.Media.Brushes.SlateGray }; var selected = new ListBox { DisplayMemberPath = "Exibicao", SelectionMode = SelectionMode.Multiple, Height = 250, MinWidth = 300, Foreground = System.Windows.Media.Brushes.Black, Background = System.Windows.Media.Brushes.White, BorderBrush = System.Windows.Media.Brushes.SlateGray }; ScrollViewer.SetVerticalScrollBarVisibility(available, ScrollBarVisibility.Auto); ScrollViewer.SetVerticalScrollBarVisibility(selected, ScrollBarVisibility.Auto); var state = new GuarnicaoState(available, selected); if (initial is not null) state.Selected.AddRange(initial); void Refresh() { var q = search.Text.Trim(); var people = _database.GetPoliciais(string.IsNullOrWhiteSpace(q) ? (string?)quartel.SelectedItem : null).Where(x => !state.Selected.Any(s => s.Id == x.Id) && (string.IsNullOrWhiteSpace(q) || x.Exibicao.Contains(q, StringComparison.OrdinalIgnoreCase))).ToList(); available.ItemsSource = people; selected.ItemsSource = state.Selected.ToList(); } var add = new Button { Content = "ADICIONAR →", Margin = new Thickness(8), VerticalAlignment = VerticalAlignment.Center }; var remove = new Button { Content = "← REMOVER", Margin = new Thickness(8), VerticalAlignment = VerticalAlignment.Center }; add.Click += (_, _) => { foreach (var p in available.SelectedItems.Cast<Policial>().ToList()) state.Selected.Add(p); Refresh(); }; remove.Click += (_, _) => { foreach (var p in selected.SelectedItems.Cast<Policial>().ToList()) state.Selected.Remove(p); Refresh(); }; search.TextChanged += (_, _) => Refresh(); quartel.SelectionChanged += (_, _) => Refresh(); Refresh(); var left = new StackPanel(); left.Children.Add(new TextBlock { Text = "POLICIAIS DISPONÍVEIS", FontWeight = FontWeights.SemiBold }); left.Children.Add(search); left.Children.Add(available); var actions = new StackPanel { VerticalAlignment = VerticalAlignment.Center }; actions.Children.Add(add); actions.Children.Add(remove); var right = new StackPanel(); right.Children.Add(new TextBlock { Text = "GUARNIÇÃO SELECIONADA", FontWeight = FontWeights.SemiBold }); right.Children.Add(selected); var row = new StackPanel { Orientation = Orientation.Horizontal, Tag = state }; row.Children.Add(left); row.Children.Add(actions); row.Children.Add(right); return row; }
    private static Natureza[] SelectedNaturezas(StackPanel box) => ((ListBox)box.Tag).SelectedItems.Cast<Natureza>().ToArray();
    private static Policial[] SelectedPoliciais(StackPanel box) => ((GuarnicaoState)box.Tag).Selected.ToArray();
    private StackPanel TimeSelector(string? value = null) { var parts = (value ?? DateTime.Now.ToString("HH:mm")).Split(':'); var h = new ComboBox { ItemsSource = Enumerable.Range(0, 24).Select(x => x.ToString("00")).ToArray(), SelectedItem = parts[0], Width = 70 }; var m = new ComboBox { ItemsSource = Enumerable.Range(0, 60).Select(x => x.ToString("00")).ToArray(), SelectedItem = parts.Length > 1 ? parts[1] : "00", Width = 70 }; var p = new StackPanel { Orientation = Orientation.Horizontal, Tag = (h, m) }; p.Children.Add(h); p.Children.Add(new TextBlock { Text = " : ", VerticalAlignment = VerticalAlignment.Center }); p.Children.Add(m); return p; }
    private static string ReadTime(StackPanel selector) { var parts = ((ComboBox, ComboBox))selector.Tag; return $"{parts.Item1.SelectedItem}:{parts.Item2.SelectedItem}"; }
    private static StackPanel SideBySide(UIElement first, UIElement second) { var p = new StackPanel { Orientation = Orientation.Horizontal }; p.Children.Add(first); p.Children.Add(new Border { Width = 18 }); p.Children.Add(second); return p; }
    private void Add(string label, UIElement control) { PageHost.Children.Add(new TextBlock { Text = label, Margin = new Thickness(0, 8, 0, 4), FontWeight = FontWeights.SemiBold }); PageHost.Children.Add(control); }
    private sealed class GuarnicaoState { public List<Policial> Selected { get; } = new(); public GuarnicaoState(ListBox available, ListBox selected) { } }
    private void Logout_Click(object s, RoutedEventArgs e) { _session = null; LoginInput.Clear(); PasswordInput.Clear(); LoginError.Text = ""; ShowLogin(); }
}
